<?php
$q=trim((string)($_GET['q']??''));$pageNo=max(1,(int)($_GET['p']??1));$perPage=10;$where=$q!==''?'WHERE (p.nama_pelanggan LIKE ? OR p.no_member LIKE ? OR p.no_hp LIKE ?)':'';$args=$q!==''?["%$q%","%$q%","%$q%"]:[];
$count=$db->prepare("SELECT COUNT(*) FROM tbl_pelanggan p {$where}");$count->execute($args);$total=(int)$count->fetchColumn();$offset=($pageNo-1)*$perPage;
$stmt=$db->prepare("SELECT p.*,COALESCE((SELECT saldo FROM tbl_saldo_pelanggan s WHERE s.id_pelanggan=p.id_pelanggan AND s.jenis_saldo='tabungan'),0) tabungan,COALESCE((SELECT saldo FROM tbl_saldo_pelanggan s WHERE s.id_pelanggan=p.id_pelanggan AND s.jenis_saldo='ewallet'),0) ewallet FROM tbl_pelanggan p {$where} ORDER BY p.id_pelanggan DESC LIMIT {$perPage} OFFSET {$offset}");$stmt->execute($args);$rows=$stmt->fetchAll();
?>
<div class="page-heading"><div><span class="section-kicker">PROGRAM MEMBER</span><h1>Pelanggan & Member</h1><p>Kelola data pelanggan dan saldo simulasi belanja mereka.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#customerModal"><i class="bi bi-person-plus me-2"></i>Tambah Pelanggan</button></div>
